(function(){if(!window.fetch||window.__kFeedPaged)return;window.__kFeedPaged=1;var orig0=window.fetch.bind(window),PER=50;/* v175: identical feed requests on one page share a single download */var memo={};function fkey(u){var q=u.split("#")[0].split("?");var ps=(q[1]||"").split("&").filter(Boolean).sort();return q[0].replace(/^https?:\/\/[^\/]+/,"")+"?"+ps.join("&")}var orig=function(u,init){if(typeof u!=="string"||(init&&init.method&&init.method!=="GET")||!/\/feeds\/posts\//.test(u))return orig0(u,init);var k=fkey(u),p=memo[k];if(!p){p=memo[k]=orig0(u,init).then((function(r){if(!r.ok)delete memo[k];return r}),(function(e){delete memo[k];throw e}))}return p.then((function(r){return r.clone()}))};window.fetch=function(input,init){try{var url=typeof input==="string"?input:"";var m=url&&/\/feeds\/posts\/(summary|default)(\/-\/[^?]*)?\?/.test(url)&&/[?&]alt=json/.test(url)&&!/[?&]start-index=/.test(url)&&url.match(/[?&]max-results=(\d+)/);if(m&&+m[1]>PER){var want=+m[1],base=url.replace(/([?&])max-results=\d+/,"$1max-results="+PER);var first=null,all=[];var page=function(start){return orig(base+"&start-index="+start,init).then((function(r){if(!r.ok)throw new Error("feed "+r.status);return r.json()})).then((function(j){var f=j.feed||(j.feed={}),e=f.entry||[];if(!first)first=j;all=all.concat(e);var tot=f.openSearch$totalResults?+f.openSearch$totalResults.$t:0;var more=tot?all.length<Math.min(want,tot)&&e.length>0:e.length===PER&&all.length<want;if(more&&start<3e3)return page(start+PER);first.feed.entry=all.slice(0,want);return new Response(JSON.stringify(first),{status:200,headers:{"Content-Type":"application/json"}})}))};return page(1).catch((function(){return orig(input,init)}))}}catch(e){}return orig(input,init)}})();
(function(){var p=location.pathname;if(/^\/\d{4}\/\d{2}\/\d{2}\/[^\/]+\/?$|^\/(category|tag)\/[^\/]+|^\/(feed|comments\/feed|page\/\d+|author\/[^\/]+)\/?$/.test(p)){document.documentElement.className+=" k-redirecting";setTimeout((function(){document.documentElement.className=document.documentElement.className.replace(" k-redirecting","")}),8e3)}})();

