window.kafkaLd=function(el){try{if(!el||el.type!=="text/x-kafka-ld")return;var t=el.textContent.replace(/\\x([0-9a-fA-F]{2})/g,"\\u00$1");var o=JSON.parse(t),ta=document.createElement("textarea");var fix=function(v){if(typeof v==="string"){if(v.indexOf("&")>-1){ta.innerHTML=v;v=ta.value}return v.replace(/\s+/g," ").trim()}if(Object.prototype.toString.call(v)==="[object Array]"){var a=[];for(var i=0;i<v.length;i++){var x=fix(v[i]);if(x!=="")a.push(x)}return a}if(v&&typeof v==="object"){for(var k in v){if(v.hasOwnProperty(k)){var y=fix(v[k]);if(y===""||y==null)delete v[k];else v[k]=y}}}return v};o=fix(o);if(o["@type"]==="BlogPosting"){if(!o.inLanguage)o.inLanguage=/[\u0900-\u097F]/.test(o.headline||"")?"ne":"en";if(o.keywords)o.keywords=o.keywords.replace(/\s*,\s*/g,", ");if(!o.image){var im=document.querySelector('meta[property="og:image"]');if(im&&im.content)o.image=im.content}}var s=document.createElement("script");s.type="application/ld+json";s.text=JSON.stringify(o);el.parentNode.insertBefore(s,el.nextSibling)}catch(e){}};

