(function(){
 if(window.__kImgFit)return;window.__kImgFit=1;
 var RE=/^(https:\/\/lh3\.googleusercontent\.com\/d\/[^=]+)=w(\d+)$/;
 var dpr=Math.min(window.devicePixelRatio||1,2);
 var Q=[],raf=0;
 function fit(img){
