 function flush(){raf=0;var q=Q;Q=[];
  var ws=q.map(function(x){var img=x[0],w=img.getBoundingClientRect().width;
   if(!w){var p=img.parentElement;while(p&&!w){w=p.getBoundingClientRect().width;p=p.parentElement;if(w>window.innerWidth)w=window.innerWidth;}}return w});
