  else{var main=t.replace(/\s*\(.*?\)\s*/g,' ').trim();var ne=/[\u0900-\u097F]/.test(main);
   var kick=kind==='songs'?(tag||shelf):kind==='movies'?(tag||shelf):kind==='series'?(tag||shelf):shelf;
