/* v170 captions: drop auto-caption when the author already wrote one */
(function(){
 function norm(s){return (s||'').replace(/[\s\u00a0]+/g,' ').trim()}
 function empty(e){return !norm(e.textContent)&&!(e.querySelector&&e.querySelector('img,iframe,video'))}
 function run(){var pr=document.querySelector('.prose');if(!pr)return;
  [].slice.call(pr.querySelectorAll('.kimg-cap')).forEach(function(c){
   var b=c;while(b.parentElement&&b.parentElement!==pr)b=b.parentElement;
   var s=b.nextElementSibling,n=0;
   while(s&&n<4&&(s.tagName==='BR'||s.classList.contains('dinkus')||empty(s))){s=s.nextElementSibling;n++}
   if(!s||/^H[1-6]$/.test(s.tagName)||s.querySelector('img:not(.dink),iframe'))return;
   var t=norm(s.textContent);if(!t)return;
   var cs=getComputedStyle(s);var it=s.querySelector('em,i');
   var looks=s.tagName!=='P'||cs.textAlign==='center'||(it&&norm(it.textContent)===t)||t.length<90||parseFloat(cs.fontSize)<parseFloat(getComputedStyle(pr).fontSize);
   if(t.length<200&&looks)c.parentNode.removeChild(c);
  });}
 run();setTimeout(run,800);setTimeout(run,2000);setTimeout(run,4500);
})();

/* v171 poem layout: poem left, photo right (top = first line), drawings under photo, ending with the poem */
(function(){
 var lastW=0;
 function q(s,r){return (r||document).querySelector(s)}
 function build(){
  var kv=document.getElementById('kview');if(!kv||kv.getAttribute('data-view')!=='post')return;
  var pr=q('.prose');var row=pr&&q('.poem-row',pr);var body=row&&q('.poem-body',row);if(!row||!body)return;
  var old=q('.kpl-col',row);
  var SKIP='.kafka-cover, .cover-slot, .cover-end, .kmore-poems, .end-doodle, .kpl-col, .related, .art-rail, .kpa-drawings';
  function ok(i){var s=i.getAttribute('src')||'';return s&&s.indexOf('data:')!==0&&(i.closest('.kpoem-photo')||!i.closest(SKIP))&&!i.classList.contains('end-doodle')}
  var img=null,fig=null;
  [].some.call(pr.querySelectorAll('figure.pic-fig img, .poem-art figure.lead-pic img, .kpoem-photo img, .poem-body img'),function(i){if(ok(i)){img=i;return true}});
  var fromCover=false;if(!img){var kc=pr.querySelector('.kafka-cover img');if(kc&&kc.getAttribute('src')&&kc.getAttribute('src').indexOf('data:')!==0){img=kc;fromCover=true}} /* v180: no picture in the poem itself -> use the post's featured picture */
  if(img&&!fromCover)fig=img.closest('figure.pic-fig, figure.lead-pic');
  var capT='';
  if(fig){var fcap=q('figcaption',fig);capT=fcap?fcap.textContent.trim():''}
  if(!capT&&img&&!fromCover){var hp0=img.closest('p,div');var n=hp0&&hp0.nextElementSibling;if(n&&n.classList&&n.classList.contains('kimg-cap'))capT=n.textContent.trim();var t=(img.getAttribute('title')||img.getAttribute('alt')||'').trim();if(!capT&&t&&!/\.(jpe?g|png|webp|gif)$/i.test(t)&&t.length<140)capT=t}
  var srcs=[].map.call(row.querySelectorAll('.kpa-drawings .pa-item img'),function(i){return i.getAttribute('src')}).filter(Boolean);
  if(!srcs.length)srcs=[].map.call(pr.querySelectorAll('.art-rail > img'),function(i){return i.getAttribute('src')}).filter(Boolean);
  if(!img&&!srcs.length)return;
  if(old)old.parentNode.removeChild(old);
  [].forEach.call(row.querySelectorAll('.kpl-moved'),function(e){e.classList.remove('kpl-moved')});
  pr.classList.add('kpl');
  var col=document.createElement('div');col.className='kpl-col';col.setAttribute('aria-hidden','true');
  var inner=document.createElement('div');inner.className='kpl-in';col.appendChild(inner);
  if(img){
   var f=document.createElement('figure');f.className='kpl-photo';
   var ci=document.createElement('img');ci.alt=img.getAttribute('alt')||'';ci.src=img.currentSrc||img.getAttribute('src');ci.decoding='async';f.appendChild(ci);
   if(capT){var fc=document.createElement('figcaption');fc.textContent=capT;if(/[\u0900-\u097F]/.test(fc.textContent))fc.lang='ne';f.appendChild(fc)}
   inner.appendChild(f);
   pr.classList.add('kpl-hasphoto');
   var hide=fig||img.closest('p')||img;hide.classList.add('kpl-moved');var nx=hide.nextElementSibling;if(!fig&&nx&&nx.classList&&nx.classList.contains('kimg-cap'))nx.classList.add('kpl-moved');[].forEach.call(row.querySelectorAll('.poem-body figure.pic-fig, .poem-body > p'),function(e){var ii=e.querySelector('img');if(ii&&(ii.currentSrc||ii.src)===(img.currentSrc||img.src))e.classList.add('kpl-moved')});
  }
  var dr=document.createElement('div');dr.className='kpl-draw';inner.appendChild(dr);
  row.appendChild(col);
  function fillDraw(){
   dr.innerHTML='';
   var avail=dr.clientHeight, w=dr.clientWidth||100, per=Math.max(w*1.05,110)+40;
   var n=Math.min(srcs.length,Math.floor(avail/per));
   for(var k=0;k<n;k++){var di=document.createElement('img');di.alt='';di.src=srcs[k];dr.appendChild(di)}
  }
  var ph=q('.kpl-photo img',inner);
  if(ph&&!ph.complete)ph.addEventListener('load',fillDraw);
  fillDraw();setTimeout(fillDraw,1200);
 }
 function run(){lastW=window.innerWidth;try{build()}catch(e){}}
 if(document.readyState==='complete')setTimeout(run,60);else{if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();window.addEventListener('load',function(){setTimeout(run,60)})}
 setTimeout(run,2500);
 window.addEventListener('resize',function(){if(Math.abs(window.innerWidth-lastW)<2)return;clearTimeout(run.t);run.t=setTimeout(run,350)});
})();

