  window.addEventListener('scroll',st,{passive:true});st();
 }catch(e){}});

 /* collection / tag headings on one line */
 function fit(){qa('h1').forEach(function(h){if(!h.querySelector(':scope > .sl'))return;h.style.fontSize='';var p=h.parentElement;var avail=p.clientWidth-(parseFloat(getComputedStyle(p).paddingLeft)||0)-(parseFloat(getComputedStyle(p).paddingRight)||0);var fs=parseFloat(getComputedStyle(h).fontSize),n=0;while(h.scrollWidth>avail+1&&fs>15&&n<40){fs-=1;h.style.fontSize=fs+'px';n++}})}
