  var lang=deck.getAttribute('lang')||'';var ne=lang==='ne';
  var nm=q('.kd-name',deck),cnt=q('.kd-cnt',deck),tag=q('.kd-tag',deck);
  var h=document.createElement('nav');h.className='kser-hero';if(lang)h.setAttribute('lang',lang);h.setAttribute('aria-label',(nm&&nm.textContent)||'Series');
  var head='<div class="ksh-head"><span class="ksh-tag"></span><a class="ksh-name"></a><span class="ksh-cnt"></span></div><ol></ol><div class="ksh-nav"></div>';h.innerHTML=head;
  q('.ksh-tag',h).textContent=tag?tag.textContent:(ne?'श्रृङ्खला':'Series');
  var a=q('.ksh-name',h);if(nm){a.textContent=nm.textContent;a.href=nm.getAttribute('href')}
  q('.ksh-cnt',h).textContent=cnt?cnt.textContent:'';
  var ol=q('ol',h),cur=-1;
  items.forEach(function(li,i){var o=document.createElement('li');var src=li.querySelector('a');var t=(src||li.querySelector('span:not(.kn)')||li).textContent.trim();var el=document.createElement(src?'a':'span');if(src)el.href=src.getAttribute('href');var n=document.createElement('span');n.className='ksh-n';n.textContent=i+1;var tt=document.createElement('span');tt.className='ksh-t';tt.textContent=t;el.appendChild(n);el.appendChild(tt);o.appendChild(el);if(li.classList.contains('is-cur')){o.className='is-cur';cur=i}ol.appendChild(o)});
  var nv=q('.ksh-nav',h);
  function link(i,cls,lab){var s=items[i]&&items[i].querySelector('a');if(!s)return;var x=document.createElement('a');x.className=cls;x.href=s.getAttribute('href');x.textContent=lab;nv.appendChild(x)}
  if(cur>0)link(cur-1,'ksh-prev',ne?'‹ अघिल्लो भाग':'‹ Previous part');
  if(cur>=0&&cur<items.length-1)link(cur+1,'ksh-next',(ne?'अर्को भाग: ':'Next: ')+items[cur+1].textContent.replace(/^\s*\d+\.\s*/,'').trim()+' ›');
  if(!nv.children.length)nv.parentNode.removeChild(nv);
  mini.parentNode.insertBefore(h,mini);document.body.classList.add('kser-hero-on');
