    box.innerHTML=list.map(function(p){var ne=isNe(p.title);return '<a class="k5" href="'+esc(p.url)+'"><span class="k5-img" style="background-image:url(\''+esc((p.img||'').replace(/([=/])w480-rw/,'$1w180-rw'))+'\')"></span><span class="k5-b"><span class="k5-t"'+(ne?' lang="ne"':'')+'>'+esc(p.title)+'</span><span class="k5-d">'+esc(p.date)+'</span></span></a>'}).join('')+'<a class="k5-more" href="'+more+'">'+(l==='ne'?'सबै नेपाली लेख ›':l==='en'?'All English posts ›':'Everything ›')+'</a>';
