 /* 2. wheels: ‹ › pager with counter, endless, follows the All / नेपाली / English choice (v172) */
 function L(){return document.documentElement.getAttribute('data-klang')||'all'}
 function wheels(){
  qa('.wheel-plane').forEach(function(p,pi){
