    var ok=x.labels.filter(function(l){return !/^(lang-|series-)|^(Nepali|English)$/i.test(l)});var lab=ok.filter(function(l){return /^(History|Science|Poetry|Letters|Stories|Books|Movies|Songs|Musings|Articles)$/.test(l)})[0]||ok[0]||'';
