   var cols=main.clientWidth>620?2:1;t.style.gridTemplateColumns='repeat('+cols+',minmax(0,1fr))';var  rows=Math.max(1,Math.floor((gap-24)/300)), n=Math.min(10,rows*cols), seen=[];
