 function thumb(u){if(!u)return '';if(/googleusercontent\.com\/d\//.test(u))return u.replace(/=[^\/]*$/,'')+'=w180-rw';return u.replace(/\/s\d+(-c)?\//,'/w180/').replace(/=s\d+(-c)?$/,'=w180')}
 var cache={};
 function rk(list,pop,l){var seen={},out=[];pop.filter(function(p){return p.lang===l}).concat(list).forEach(function(p){if(p&&!seen[p.url]){seen[p.url]=1;out.push(p)}});return out}
 function feed(lang){var k=lang||'all';if(cache[k])return cache[k];
  cache[k]=fetch('/feeds/posts/summary'+(lang==='ne'?'/-/Nepali':lang==='en'?'/-/English':'')+'?alt=json&max-results=15').then(function(r){return r.json()}).then(function(j){
   return ((j.feed&&j.feed.entry)||[]).map(function(e){var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0];
    return {url:l?l.href:'',title:(e.title&&e.title.$t)||'',img:thumb(e.media$thumbnail&&e.media$thumbnail.url),date:fdate(e.published&&e.published.$t)}})}).catch(function(){delete cache[k];return []});
  return cache[k]}
 var allP=null;
 function pathOf(u){return String(u||'').replace(/^https?:\/\/[^\/]+/,'').split(/[?#]/)[0]}
 function norm(t){return String(t||'').replace(/\s+/g,' ').trim().toLowerCase()}
 function allPosts(){if(!allP)allP=fetch('/feeds/posts/summary?alt=json&max-results=500').then(function(r){return r.json()}).then(function(j){var by={},bt={};
   ((j.feed&&j.feed.entry)||[]).forEach(function(e){var l=(e.link||[]).filter(function(x){return x.rel==='alternate'})[0];if(!l)return;var cats=(e.category||[]).map(function(c){return c.term});var t=(e.title&&e.title.$t)||'';
    var p={url:l.href,title:t,img:thumb(e.media$thumbnail&&e.media$thumbnail.url),date:fdate(e.published&&e.published.$t),lang:cats.indexOf('Nepali')>-1?'ne':cats.indexOf('English')>-1?'en':(isNe(t)?'ne':'en')};by[pathOf(l.href)]=p;bt[norm(t)]=p});return {by:by,bt:bt}}).catch(function(){allP=null;return {by:{},bt:{}}});return allP}
 /* Most read: Blogger's own popular-posts list (server-rendered in #kafka-pop), filled in from the post list */
 function popular(){return allPosts().then(function(m){var seen={};return [].map.call(document.querySelectorAll('#kafka-pop a'),function(a){var h=a.getAttribute('href');return (h&&m.by[pathOf(h)])||m.bt[norm(a.textContent)]||null}).filter(function(p){if(!p||seen[p.url])return false;seen[p.url]=1;return true})})}
 function row(p){var ne=isNe(p.title);return '<a class="k5" href="'+esc(p.url)+'"><span class="k5-img"'+(p.img?' style="background-image:url(\''+esc(p.img)+'\')"':'')+'></span><span class="k5-b"><span class="k5-t"'+(ne?' lang="ne"':'')+'>'+esc(p.title)+'</span><span class="k5-d">'+esc(p.date)+'</span></span></a>'}
 function col(cls,ne,en,list,more,moreTxt,note){return '<div class="k3col '+cls+'"><p class="k3h"><span lang="ne">'+ne+'</span> <span class="k3en">'+en+'</span></p>'+list.map(row).join('')+(note||'')+(more?'<a class="k5-more" href="'+more+'">'+moreTxt+'</a>':'')+'</div>'}
 var box=null,cur=null,tok=0;
 function draw(l){
  if(!box)return;cur=l;var my=++tok;box.classList.add('is-loading');
  if(l==='ne'||l==='en'){
   Promise.all([feed(l),popular()]).then(function(rr){var list=rr[0],pop=rr[1];if(my!==tok)return;
    var lp=pop.filter(function(p){return p.lang===l}).slice(0,5),seen={};lp.forEach(function(p){seen[p.url]=1});var rest=list.filter(function(p){return !seen[p.url]});rest.slice(0,10).forEach(function(p){seen[p.url]=1});
    var fill=rest.slice(10).filter(function(p){return !seen[p.url]}).slice(0,5-lp.length);
    var L=l==='ne';
    box.innerHTML=col('k3a',L?'नयाँ':'नयाँ','Top picks',rest.slice(0,5),L?'/search/label/Nepali':'/search/label/English',L?'सबै नेपाली लेख ›':'All English posts ›')
     +col('k3b','अघिल्ला','More',rest.slice(5,10),'/search?max-results=20',L?'सबै लेख ›':'Everything ›')
     +'<div class="k3col k3c"><p class="k3h"><span lang="ne">धेरै पढिएका</span> <span class="k3en">Most read</span></p>'+lp.map(row).join('')
       +(fill.length?'<p class="k3sub">'+(L?'पुरानो सङ्ग्रहबाट':'From the archive')+'</p>'+fill.map(row).join(''):'')+'<a class="k5-more" href="#kafka-top">'+(L?'थप ›':'More ›')+'</a></div>';
     box.classList.remove('is-loading');
   });
  }else{
   Promise.all([feed('ne'),feed('en'),popular()]).then(function(r){var pop=r[2];if(my!==tok)return;var mr=pop.slice(0,5),sn={};mr.forEach(function(p){sn[p.url]=1});var nx=function(a){return a.filter(function(p){return !sn[p.url]}).slice(0,5)};
    box.innerHTML=col('k3a','नेपाली','Nepali',nx(r[0]),'/search/label/Nepali','सबै नेपाली लेख ›')
     +col('k3b','अङ्ग्रेजी','English',nx(r[1]),'/search/label/English','All English posts ›')
     +col('k3c','धेरै पढिएका','Most read',mr,'#kafka-top','More ›');
    box.classList.remove('is-loading');
   });
  }
 }
 function lang(){var b=document.querySelector('.kd-lang button[aria-pressed="true"]');return b?b.getAttribute('data-l'):'all'}
 function setup(){
  var g=document.querySelector('.kd-lang');if(!g||document.querySelector('.kstart3'))return !!g;
  box=document.createElement('div');box.className='kstart3';box.setAttribute('aria-live','polite');
  var after=document.querySelector('.kstart5')||g;after.parentNode.insertBefore(box,after.nextSibling);
  document.documentElement.classList.add('k3-on');
  g.addEventListener('click',function(ev){var b=ev.target.closest('button[data-l]');if(b)setTimeout(function(){draw(b.getAttribute('data-l'))},0)});
  if(MQ.matches)draw(lang());
  var mqf=function(){if(MQ.matches&&cur===null)draw(lang())};if(MQ.addEventListener)MQ.addEventListener('change',mqf);else MQ.addListener(mqf);
  return true}
 function go(){if(!setup()){var n=0;(function t(){if(setup()||n++>40)return;setTimeout(t,250)})()}}
 if(document.readyState!=='loading')go();else document.addEventListener('DOMContentLoaded',go);
})();
